//! Prints the measured-room evidence used by the "Real rooms" section of
//! `ROBUSTNESS.md`.
//!
//! ```text
//! cargo run --release -p cf-aec --example real_rir_report
//! ```
//!
//! The table is generated by the same scene generator, measurement windows and
//! production configuration as `tests/real_rir_conditions.rs`; the report and
//! the assertions cannot drift apart. Every printed number is deterministic:
//! the scenes are seeded and the WAV responses are compiled into the example.
//! CPU is not printed, because it is machine-dependent and the real-room claim
//! does not depend on it.

#[path = "../tests/room/mod.rs"]
mod room;

use room::{
    mean_min_max, real_c50_db, real_rt20_s, run_real_matrix, run_scene, scenes, DelayKind, Metrics,
    NoiseKind, RealCondition, RealSceneRuns, RirKind, SceneSpec, REAL_RIRS, SEEDS,
};

fn main() {
    let real = run_real_matrix();
    print_policy(&real);
    print_per_rir(&real);
    let real_aggregates = print_real_aggregates(&real);
    print_campaign_aggregates(&real);
    print_rt_bands(&real);
    let synthetic = run_synthetic();
    let synthetic_aggregates = matched_synthetic_aggregates(&synthetic);
    print_comparison(&real_aggregates, &synthetic_aggregates);
    print_synthetic_families(&synthetic);
    print_flags(&real);
}

fn print_policy(real: &[RealSceneRuns]) {
    println!("## Real measured rooms\n");
    println!(
        "18 responses, 4 conditions each, {} seeds = {} runs. Every response is \
         loaded from the WAV bundled next to `real/PROVENANCE.md`, reduced to \
         channel 0 where the source is multi-channel, resampled from 48 kHz to \
         16 kHz where needed, and normalised to unit L2 energy. The generator, \
         the 30 ms static bulk delay, the noise scaling and the near-end scaling \
         are the same code and the same rules as the synthetic matrix. The AEC \
         runs the production `AecConfig::default()` with clock-rate correction \
         on (it stays bypassed on these static paths).",
        SEEDS.len(),
        real.len() * SEEDS.len()
    );
    println!();
}

fn print_per_rir(real: &[RealSceneRuns]) {
    println!("### Per measured response\n");
    println!(
        "| id | campaign | room / microphone | taps | RT20 (s) | C50 (dB) | clean | DT -6 dB | DT +3 dB | pink 15 dB | mean of 4 |"
    );
    println!("| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
    for rir in &REAL_RIRS {
        let impulse = rir.cached_impulse();
        let cells: Vec<String> = RealCondition::ALL
            .iter()
            .map(|condition| format!("{:.1}", mean(&values_for(real, rir.id, *condition))))
            .collect();
        let condition_means: Vec<f32> = RealCondition::ALL
            .iter()
            .map(|condition| mean(&values_for(real, rir.id, *condition)))
            .collect();
        println!(
            "| {} | {} | {} | {} | {:.3} | {:.1} | {} | {} | {} | {} | {:.1} |",
            rir.id,
            rir.dataset,
            rir.room,
            impulse.len(),
            real_rt20_s(impulse).unwrap_or(f32::NAN),
            real_c50_db(impulse),
            cells[0],
            cells[1],
            cells[2],
            cells[3],
            mean(&condition_means),
        );
    }
    let columns: Vec<Vec<f32>> = RealCondition::ALL
        .iter()
        .map(|condition| {
            REAL_RIRS
                .iter()
                .map(|rir| mean(&values_for(real, rir.id, *condition)))
                .collect()
        })
        .collect();
    let all: Vec<f32> = columns.iter().flatten().copied().collect();
    for label in ["mean", "min", "max"] {
        let value = |values: &[f32]| match label {
            "mean" => mean(values),
            "min" => values.iter().copied().fold(f32::INFINITY, f32::min),
            _ => values.iter().copied().fold(f32::NEG_INFINITY, f32::max),
        };
        let overall = match label {
            "mean" => mean(&all),
            "min" => all.iter().copied().fold(f32::INFINITY, f32::min),
            _ => all.iter().copied().fold(f32::NEG_INFINITY, f32::max),
        };
        println!(
            "| **{label} over 18 rooms** | | | | | | {:.1} | {:.1} | {:.1} | {:.1} | {:.1} |",
            value(&columns[0]),
            value(&columns[1]),
            value(&columns[2]),
            value(&columns[3]),
            overall,
        );
    }
    println!();
}

fn values_for(real: &[RealSceneRuns], id: &str, condition: RealCondition) -> Vec<f32> {
    real.iter()
        .filter(|scene| {
            scene.spec.real_rir == Some(id)
                && scene.spec.near_db == condition.near_db()
                && scene.spec.noise == condition.noise()
        })
        .flat_map(|scene| scene.runs.iter().map(|metrics| metrics.echo_erle_post_db))
        .collect()
}

#[derive(Clone, Copy)]
struct Aggregate {
    mean: f32,
    min: f32,
    max: f32,
    runs: usize,
}

fn aggregate(values: &[f32]) -> Aggregate {
    match mean_min_max(values) {
        Some((mean, min, max)) => Aggregate {
            mean,
            min,
            max,
            runs: values.len(),
        },
        None => Aggregate {
            mean: f32::NAN,
            min: f32::NAN,
            max: f32::NAN,
            runs: 0,
        },
    }
}

fn print_real_aggregates(real: &[RealSceneRuns]) -> Vec<(String, Aggregate)> {
    println!("### Real-room aggregate\n");
    println!("| Condition | Rooms | Seeds/room | Echo ERLE post mean (dB) | min (dB) | max (dB) |");
    println!("| --- | ---: | ---: | ---: | ---: | ---: |");
    let mut out = Vec::new();
    for condition in RealCondition::ALL {
        // Equal weight per room: average the three seeds inside a room, then
        // take mean/min/max across the 18 rooms.
        let per_room: Vec<f32> = REAL_RIRS
            .iter()
            .map(|rir| mean(&values_for(real, rir.id, condition)))
            .collect();
        let aggregate = aggregate(&per_room);
        println!(
            "| {} | {} | {} | {:.1} | {:.1} | {:.1} |",
            condition.label(),
            per_room.len(),
            SEEDS.len(),
            aggregate.mean,
            aggregate.min,
            aggregate.max
        );
        out.push((condition.label().to_string(), aggregate));
    }
    let per_room: Vec<f32> = REAL_RIRS
        .iter()
        .map(|rir| {
            let condition_means: Vec<f32> = RealCondition::ALL
                .iter()
                .map(|condition| mean(&values_for(real, rir.id, *condition)))
                .collect();
            mean(&condition_means)
        })
        .collect();
    let aggregate = aggregate(&per_room);
    println!(
        "| all four conditions | {} | {} | {:.1} | {:.1} | {:.1} |",
        per_room.len(),
        SEEDS.len() * RealCondition::ALL.len(),
        aggregate.mean,
        aggregate.min,
        aggregate.max
    );
    out.push(("all four conditions".to_string(), aggregate));
    println!();
    out
}

fn print_campaign_aggregates(real: &[RealSceneRuns]) {
    println!("### By measurement campaign\n");
    println!(
        "| Campaign | Rooms | Mean echo ERLE post (dB) | min (dB) | max (dB) | Clean mean (dB) |"
    );
    println!("| --- | ---: | ---: | ---: | ---: | ---: |");
    let mut campaigns: Vec<&str> = Vec::new();
    for rir in &REAL_RIRS {
        if !campaigns.contains(&rir.dataset) {
            campaigns.push(rir.dataset);
        }
    }
    for campaign in campaigns {
        let per_room: Vec<f32> = REAL_RIRS
            .iter()
            .filter(|rir| rir.dataset == campaign)
            .map(|rir| {
                let condition_means: Vec<f32> = RealCondition::ALL
                    .iter()
                    .map(|condition| mean(&values_for(real, rir.id, *condition)))
                    .collect();
                mean(&condition_means)
            })
            .collect();
        let clean: Vec<f32> = REAL_RIRS
            .iter()
            .filter(|rir| rir.dataset == campaign)
            .map(|rir| mean(&values_for(real, rir.id, RealCondition::Clean)))
            .collect();
        let aggregate = aggregate(&per_room);
        println!(
            "| {campaign} | {} | {:.1} | {:.1} | {:.1} | {:.1} |",
            per_room.len(),
            aggregate.mean,
            aggregate.min,
            aggregate.max,
            mean(&clean)
        );
    }
    println!();
}

fn print_rt_bands(real: &[RealSceneRuns]) {
    println!("### By measured reverberation time\n");
    println!(
        "| RT20 band | Rooms | Clean mean (dB) | All-condition mean (dB) | min (dB) | max (dB) |"
    );
    println!("| --- | ---: | ---: | ---: | ---: | ---: |");
    let bands = [
        ("< 0.20 s", 0.0f32, 0.20f32),
        ("0.20-0.40 s", 0.20, 0.40),
        ("0.40-0.70 s", 0.40, 0.70),
        (">= 0.70 s", 0.70, f32::INFINITY),
    ];
    for (label, low, high) in bands {
        let rooms: Vec<&str> = REAL_RIRS
            .iter()
            .filter(|rir| {
                let rt = real_rt20_s(rir.cached_impulse()).unwrap_or(f32::NAN);
                rt >= low && rt < high
            })
            .map(|rir| rir.id)
            .collect();
        if rooms.is_empty() {
            continue;
        }
        let clean: Vec<f32> = REAL_RIRS
            .iter()
            .filter(|rir| rooms.contains(&rir.id))
            .map(|rir| mean(&values_for(real, rir.id, RealCondition::Clean)))
            .collect();
        let per_room: Vec<f32> = REAL_RIRS
            .iter()
            .filter(|rir| rooms.contains(&rir.id))
            .map(|rir| {
                let condition_means: Vec<f32> = RealCondition::ALL
                    .iter()
                    .map(|condition| mean(&values_for(real, rir.id, *condition)))
                    .collect();
                mean(&condition_means)
            })
            .collect();
        let aggregate = aggregate(&per_room);
        println!(
            "| {label} | {} | {:.1} | {:.1} | {:.1} | {:.1} |",
            rooms.len(),
            mean(&clean),
            aggregate.mean,
            aggregate.min,
            aggregate.max
        );
    }
    println!();
}

fn run_synthetic() -> Vec<RealSceneRuns> {
    scenes()
        .into_iter()
        .map(|spec| {
            let runs = SEEDS
                .iter()
                .map(|&seed| run_scene(&spec, seed).metrics)
                .collect();
            RealSceneRuns { spec, runs }
        })
        .collect()
}

/// Predicate selecting the synthetic scenes that match one real-room condition.
type SyntheticMatcher = fn(&SceneSpec) -> bool;

fn matched_synthetic_aggregates(synthetic: &[RealSceneRuns]) -> Vec<(String, Aggregate)> {
    let groups: [(RealCondition, SyntheticMatcher); 4] = [
        (RealCondition::Clean, |spec| {
            spec.noise.is_none()
                && spec.near_db.is_none()
                && spec.delay == DelayKind::Static
                && spec.real_rir.is_none()
        }),
        (RealCondition::NearMinus6, |spec| {
            spec.near_db == Some(-6.0) && spec.noise.is_none() && spec.delay == DelayKind::Static
        }),
        (RealCondition::NearPlus3, |spec| {
            spec.near_db == Some(3.0) && spec.noise.is_none() && spec.delay == DelayKind::Static
        }),
        (RealCondition::Pink15, |spec| {
            spec.noise == Some((NoiseKind::Pink, 15.0))
                && spec.near_db.is_none()
                && spec.delay == DelayKind::Static
        }),
    ];
    let mut out = Vec::new();
    let mut condition_means = Vec::new();
    for (condition, predicate) in groups {
        let values: Vec<f32> = synthetic
            .iter()
            .filter(|scene| predicate(&scene.spec))
            .flat_map(|scene| scene.runs.iter().map(|metrics| metrics.echo_erle_post_db))
            .collect();
        let aggregate = aggregate(&values);
        condition_means.push(aggregate.mean);
        out.push((condition.label().to_string(), aggregate));
    }
    // Match the real set's weighting (four conditions per room contribute
    // equally) by averaging the four condition means. The run count is the
    // number of synthetic runs behind that average.
    let runs = out.iter().map(|(_, aggregate)| aggregate.runs).sum();
    out.push((
        "all four conditions".to_string(),
        Aggregate {
            mean: mean(&condition_means),
            min: out
                .iter()
                .map(|(_, aggregate)| aggregate.min)
                .fold(f32::INFINITY, f32::min),
            max: out
                .iter()
                .map(|(_, aggregate)| aggregate.max)
                .fold(f32::NEG_INFINITY, f32::max),
            runs,
        },
    ));
    out
}

fn print_comparison(real: &[(String, Aggregate)], synthetic: &[(String, Aggregate)]) {
    println!("### Real vs synthetic, matched conditions\n");
    println!(
        "| Condition | Real mean | Real min | Real max | Synthetic mean | Synthetic min | Synthetic max | Delta (real - synthetic) |"
    );
    println!("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
    for (label, real) in real {
        if let Some((_, synthetic)) = synthetic.iter().find(|(name, _)| name == label) {
            println!(
                "| {label} | {:.1} | {:.1} | {:.1} | {:.1} | {:.1} | {:.1} | {:+.1} |",
                real.mean,
                real.min,
                real.max,
                synthetic.mean,
                synthetic.min,
                synthetic.max,
                real.mean - synthetic.mean
            );
        }
    }
    println!();
}

fn print_synthetic_families(synthetic: &[RealSceneRuns]) {
    println!("### Synthetic room-family aggregate (existing matrix)\n");
    println!(
        "| Room family | Runs | Echo ERLE post mean (dB) | min (dB) | max (dB) | Clean mean (dB) |"
    );
    println!("| --- | ---: | ---: | ---: | ---: | ---: |");
    for rir in RirKind::ALL {
        let values: Vec<f32> = synthetic
            .iter()
            .filter(|scene| scene.spec.rir == rir && scene.spec.real_rir.is_none())
            .flat_map(|scene| scene.runs.iter().map(|metrics| metrics.echo_erle_post_db))
            .collect();
        let clean: Vec<f32> = synthetic
            .iter()
            .filter(|scene| {
                scene.spec.rir == rir
                    && scene.spec.real_rir.is_none()
                    && scene.spec.noise.is_none()
                    && scene.spec.near_db.is_none()
                    && scene.spec.delay == DelayKind::Static
            })
            .flat_map(|scene| scene.runs.iter().map(|metrics| metrics.echo_erle_post_db))
            .collect();
        let aggregate = aggregate(&values);
        println!(
            "| {} | {} | {:.1} | {:.1} | {:.1} | {:.1} |",
            rir.label(),
            aggregate.runs,
            aggregate.mean,
            aggregate.min,
            aggregate.max,
            mean(&clean)
        );
    }
    println!();
}

fn print_flags(real: &[RealSceneRuns]) {
    let runs: Vec<&Metrics> = real.iter().flat_map(|scene| scene.runs.iter()).collect();
    let non_finite = runs.iter().filter(|metrics| metrics.has_nan).count();
    let diverged = runs.iter().filter(|metrics| metrics.diverged).count();
    let collapsed = runs.iter().filter(|metrics| metrics.collapsed).count();
    let no_recovery = runs
        .iter()
        .filter(|metrics| metrics.has_double_talk && metrics.recovery_ms.is_none())
        .count();
    let worst_norm = runs
        .iter()
        .map(|metrics| metrics.norm_peak)
        .fold(0.0f32, f32::max);
    let engaged = runs
        .iter()
        .filter(|metrics| metrics.clock_engaged_frame.is_some())
        .count();
    let gains: Vec<f32> = runs
        .iter()
        .filter_map(|metrics| metrics.near_gain_db)
        .collect();
    let recoveries: Vec<f32> = runs
        .iter()
        .filter_map(|metrics| metrics.recovery_ms)
        .collect();
    let flags: Vec<f32> = runs
        .iter()
        .filter_map(|metrics| metrics.dt_flag_rate)
        .collect();
    println!("### Flags\n");
    println!("| Flag | Count |");
    println!("| --- | ---: |");
    println!("| Runs | {} |", runs.len());
    println!("| Non-finite output | {non_finite} |");
    println!("| Diverged (NaN, norm > 10, echo ERLE < -6 dB) | {diverged} |");
    println!("| ERLE collapse (echo ERLE post < 3 dB) | {collapsed} |");
    println!("| Recovery not reached inside the window | {no_recovery} |");
    println!("| Clock-rate correction engaged | {engaged} |");
    println!("| Worst filter norm | {worst_norm:.2} |");
    println!();
    println!("### Double-talk behaviour on the real rooms\n");
    println!("| Metric | Mean | min | max |");
    println!("| --- | ---: | ---: | ---: |");
    for (label, values) in [
        ("Near-end gain (dB)", &gains),
        ("Recovery (ms)", &recoveries),
        ("DT flag rate (%)", &flags),
    ] {
        match mean_min_max(values) {
            Some((mean, min, max)) => {
                println!("| {label} | {mean:.1} | {min:.1} | {max:.1} |")
            }
            None => println!("| {label} | - | - | - |"),
        }
    }
    println!();
    println!(
        "The real set is compared against the synthetic families with the same \
         condition definitions and the same measurement window (frames 480-620, \
         7.68-9.92 s). A positive delta means the real room did better."
    );
}

fn mean(values: &[f32]) -> f32 {
    mean_min_max(values).map_or(f32::NAN, |(mean, _, _)| mean)
}
